import * as T from './vendor/three.module.min.js';
import { SKILLS, clamp } from './core.js';
const v3=(x=0,y=0,z=0)=>new T.Vector3(x,y,z);
export class View3D {
  constructor(canvas,game,settings){
    this.canvas=canvas;this.game=game;this.settings=settings;this.fx=[];this.projectileViews=new Map();this.floating=[];this.shake=0;
    this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setClearColor('#08121c');this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.3;this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;
    this.scene=new T.Scene();this.scene.fog=new T.FogExp2('#091722',.026);this.camera=new T.PerspectiveCamera(40,1,.1,150);this.camera.position.set(17,22,23);this.baseCamera=this.camera.position.clone();this.lookAt=v3(0,0,0);this.camera.lookAt(this.lookAt);this.ray=new T.Raycaster();this.ground=new T.Plane(v3(0,1,0),0);this.pointer=new T.Vector2();this.glowMap=this.makeGlow();this.runeMap=this.makeRune();this.mat={stone:this.standard('#1b2932',.75,.15),dark:this.standard('#0c1823',.8,.2),trim:this.standard('#425e66',.5,.5),cloth:this.standard('#1d6870',.8,.15),gold:this.standard('#baa572',.5,.5)};
    const ambient=new T.HemisphereLight('#c8e9f0','#07121b',2.2);this.scene.add(ambient);const key=new T.DirectionalLight('#c5e4dd',3.2);key.position.set(9,19,7);key.castShadow=true;key.shadow.mapSize.set(1024,1024);Object.assign(key.shadow.camera,{left:-17,right:17,top:17,bottom:-17,near:1,far:65});key.shadow.bias=-.0004;this.scene.add(key);const rim=new T.DirectionalLight('#5488db',2.2);rim.position.set(-12,9,-12);this.scene.add(rim);
    this.buildArena();this.player=this.buildMage();this.scene.add(this.player.root);this.targets=game.targets.map(t=>this.buildTarget(t));this.cursor=this.buildCursor();this.scene.add(this.cursor);this.buildDust();this.resize();
    game.on('release',e=>this.onRelease(e));game.on('impact',e=>this.impact(e.x,e.z,e.kind));game.on('hit',e=>{this.floating.push({...e,life:1.15,total:1.15});this.shake=Math.max(this.shake,e.kind==='nova'?.18:.07);});game.on('reset',()=>this.clear());
  }
  standard(color,roughness=.7,metalness=.1){return new T.MeshStandardMaterial({color,roughness,metalness});}
  basic(color,opacity=1){return new T.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthWrite:opacity===1,side:T.DoubleSide});}
  mesh(geo,mat,parent,pos=[0,0,0]){const m=new T.Mesh(geo,mat);m.position.set(...pos);parent.add(m);return m;}
  cylinder(r1,r2,h,mat,parent,pos,segments=16){return this.mesh(new T.CylinderGeometry(r1,r2,h,segments),mat,parent,pos);}
  ring(radius,color,parent,y=0,tube=.018){const m=this.mesh(new T.TorusGeometry(radius,tube,6,100),this.basic(color,.7),parent,[0,y,0]);m.rotation.x=Math.PI/2;return m;}
  makeGlow(){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'#ffffff');g.addColorStop(.12,'#ffffffdd');g.addColorStop(.35,'#ffffff44');g.addColorStop(1,'#ffffff00');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);return new T.CanvasTexture(c);}
  makeRune(){const c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d');x.translate(256,256);x.strokeStyle='#c7fff2';x.lineWidth=1.2;for(const r of [194,202,241,246]){x.beginPath();x.arc(0,0,r,0,Math.PI*2);x.stroke();}for(let i=0;i<32;i++){x.save();x.rotate(i*Math.PI/16);x.translate(0,-223);x.beginPath();x.moveTo(-6,7);x.lineTo(0,-8);x.lineTo(6,7);x.moveTo(-8,0);x.lineTo(8,0);if(i%2===0){x.moveTo(0,-11);x.lineTo(0,12);}x.stroke();x.restore();}x.globalAlpha=.5;for(let i=0;i<2;i++){x.save();x.rotate(i*Math.PI/3);x.beginPath();for(let j=0;j<3;j++){const a=j*Math.PI*2/3-Math.PI/2;x.lineTo(Math.cos(a)*170,Math.sin(a)*170);}x.closePath();x.stroke();x.restore();}return new T.CanvasTexture(c);}
  glow(color,size,parent,pos=[0,0,0]){const m=new T.Sprite(new T.SpriteMaterial({map:this.glowMap,color,transparent:true,opacity:.7,blending:T.AdditiveBlending,depthWrite:false}));m.scale.set(size,size,1);m.position.set(...pos);parent.add(m);return m;}
  rune(radius,color,parent,y=.04){const p=this.mesh(new T.PlaneGeometry(radius*2,radius*2),new T.MeshBasicMaterial({map:this.runeMap,color,transparent:true,opacity:.6,side:T.DoubleSide,depthWrite:false,blending:T.AdditiveBlending}),parent,[0,y,0]);p.rotation.x=-Math.PI/2;return p;}
  buildArena(){
    const s=this.scene;this.cylinder(13.7,14.1,.7,this.mat.dark,s,[0,-.5,0],96).receiveShadow=true;this.cylinder(13.5,13.5,.13,this.mat.stone,s,[0,-.08,0],96).receiveShadow=true;const beyond=this.mesh(new T.PlaneGeometry(180,180),this.standard('#08131b'),s,[0,-.9,0]);beyond.rotation.x=-Math.PI/2;
    const grid=new T.GridHelper(26,26,'#476462','#2c424b');grid.position.y=.005;grid.material.transparent=true;grid.material.opacity=.32;s.add(grid);for(const r of [13.35,12.7,10.5])this.ring(r,r===13.35?'#7ae7ce':'#447379',s,.015,r===13.35?.025:.012);const outerRune=this.rune(12.9,'#87b3aa',s,.022);outerRune.material.opacity=.16;
    for(let i=0;i<12;i++){const a=i*Math.PI/6,x=Math.sin(a)*13.6,z=Math.cos(a)*13.6;const pillar=new T.Group();pillar.position.set(x,0,z);this.cylinder(.5,.65,.45,this.mat.dark,pillar,[0,.08,0],6);const shaft=this.cylinder(.21,.36,1.35,this.mat.stone,pillar,[0,.9,0],6);shaft.castShadow=true;this.cylinder(.37,.37,.1,this.mat.trim,pillar,[0,1.6,0],6);const shard=this.mesh(new T.OctahedronGeometry(.32),this.basic(i%3===0?'#b6f4dd':'#65b6b8'),pillar,[0,2,0]);shard.scale.y=1.9;this.glow('#5bcbcc',1.4,pillar,[0,2,0]);s.add(pillar);}
    const steps=new T.Group();for(let i=0;i<3;i++)this.mesh(new T.BoxGeometry(3.4,.25,1),this.mat.stone,steps,[0,-.35-i*.2,14+i*.6]);s.add(steps);
  }
  buildMage(){const root=new T.Group(),body=new T.Group();root.add(body);const robe=this.cylinder(.29,.52,1.02,this.mat.cloth,body,[0,1.05,0],8);robe.castShadow=true;const trim=this.cylinder(.525,.55,.08,this.mat.gold,body,[0,.54,0],8);this.mesh(new T.BoxGeometry(.54,.09,.38),this.mat.gold,body,[0,1.34,0]);const chest=this.mesh(new T.BoxGeometry(.2,.4,.025),this.mat.dark,body,[0,1.19,.3]);this.glow('#96f8df',.25,body,[0,1.24,.34]);
    const head=new T.Group();head.position.y=1.85;const hood=this.mesh(new T.SphereGeometry(.29,12,8),this.mat.dark,head);hood.scale.set(1,1.1,1.1);const cap=this.mesh(new T.ConeGeometry(.3,.5,8),this.mat.cloth,head,[0,.21,-.06]);cap.rotation.x=-.2;this.mesh(new T.SphereGeometry(.21,10,8),this.basic('#101c26'),head,[0,-.01,.19]);for(const x of [-.075,.075])this.mesh(new T.BoxGeometry(.055,.025,.03),this.basic('#a5ffee'),head,[x,.02,.376]);body.add(head);
    const cape=this.mesh(new T.ConeGeometry(.51,1.17,5,1,true,0,Math.PI),this.standard('#14343e'),body,[0,1.05,-.2]);cape.rotation.z=Math.PI;cape.rotation.y=Math.PI;cape.material.side=T.DoubleSide;
    const limbs=[];for(const side of [-1,1]){const leg=new T.Group();leg.position.set(side*.2,.6,0);const cloth=this.cylinder(.12,.11,.45,this.mat.dark,leg,[0,-.2,0],6);this.mesh(new T.BoxGeometry(.21,.18,.35),this.mat.dark,leg,[0,-.48,.08]);body.add(leg);limbs.push(leg);}
    const arms=[];for(const side of [-1,1]){const arm=new T.Group();arm.position.set(side*.4,1.52,0);this.cylinder(.13,.16,.53,this.mat.cloth,arm,[0,-.23,0],8);this.mesh(new T.SphereGeometry(.105,8,6),this.mat.gold,arm,[0,-.52,0]);body.add(arm);arms.push(arm);}
    const staff=new T.Group();staff.position.set(-.04,-.45,.2);this.cylinder(.037,.045,1.8,this.mat.gold,staff,[0,.4,0],8);const gem=this.mesh(new T.OctahedronGeometry(.18),this.basic('#a8ffea'),staff,[0,1.42,0]);gem.scale.y=1.5;this.ring(.24,'#9aeed7',staff,1.42,.012);const staffGlow=this.glow('#70f4ce',1.1,staff,[0,1.42,0]);arms[1].add(staff);
    const aura=new T.Group();const rune=this.rune(.85,'#8cf3d4',aura,.05);this.ring(.82,'#98e8d2',aura,.04,.018);root.add(aura);const chargeGlow=this.glow('#ffac64',.01,root,[0,1.6,.7]);return{root,body,head,cape,legs:limbs,arms,staff,staffGlow,aura,rune,chargeGlow};}
  buildTarget(t){const root=new T.Group();root.position.set(t.x,0,t.z);const stone=this.standard('#334653',.65,.45);const body=this.mesh(new T.IcosahedronGeometry(.57,0),stone,root,[0,1.3,0]);body.scale.set(.8,1.25,.7);body.castShadow=true;this.cylinder(.18,.28,.6,this.mat.dark,root,[0,.55,0],6);this.cylinder(.54,.63,.14,this.mat.trim,root,[0,.14,0],8);this.mesh(new T.OctahedronGeometry(.22),this.basic('#d8bb91'),root,[0,2.1,0]);for(const side of [-1,1]){const a=this.mesh(new T.BoxGeometry(.15,.65,.18),stone,root,[side*.48,1.25,0]);a.rotation.z=side*.2;}this.ring(.72,'#647e82',root,.025,.015);this.glow('#5f9ca1',1.2,root,[0,.2,0]);const hpBack=this.mesh(new T.PlaneGeometry(1.15,.065),this.basic('#19333b'),root,[0,2.7,0]);const hp=this.mesh(new T.PlaneGeometry(1.1,.04),this.basic('#a4dcc1'),root,[0,2.7,.015]);this.scene.add(root);return{root,body,hp,hpBack,stone};}
  buildCursor(){const root=new T.Group();this.ring(.48,'#9affdf',root,.04,.02);this.ring(.58,'#97ebdb',root,.04,.008);for(let i=0;i<4;i++){const a=i*Math.PI/2;const m=this.mesh(new T.ConeGeometry(.055,.2,3),this.basic('#b7fce3'),root,[Math.sin(a)*.76,.045,Math.cos(a)*.76]);m.rotation.set(Math.PI/2,0,-a);}return root;}
  buildDust(){const n=220,positions=new Float32Array(n*3);for(let i=0;i<n;i++){positions[i*3]=(Math.random()-.5)*32;positions[i*3+1]=Math.random()*9;positions[i*3+2]=(Math.random()-.5)*32;}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));this.dust=new T.Points(geometry,new T.PointsMaterial({map:this.glowMap,color:'#88c8bf',size:.09,transparent:true,opacity:.6,depthWrite:false,blending:T.AdditiveBlending}));this.scene.add(this.dust);}
  resize(){const w=this.canvas.parentElement.clientWidth,h=this.canvas.parentElement.clientHeight;this.renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,{low:1,medium:1.4,high:2}[this.settings.quality]));this.renderer.setSize(w,h,false);this.camera.aspect=w/h;const distance=w<600?1.35:1;this.baseCamera.set(17*distance,22*distance,23*distance);this.camera.position.copy(this.baseCamera);this.camera.lookAt(this.lookAt);this.camera.updateProjectionMatrix();}
  aim(clientX,clientY){const r=this.canvas.getBoundingClientRect();this.pointer.set((clientX-r.left)/r.width*2-1,-(clientY-r.top)/r.height*2+1);this.ray.setFromCamera(this.pointer,this.camera);const out=v3();if(this.ray.ray.intersectPlane(this.ground,out))this.game.setAim(out.x,out.z);}
  project(x,y,z){const v=v3(x,y,z).project(this.camera);return{x:(v.x*.5+.5)*this.canvas.clientWidth,y:(-.5*v.y+.5)*this.canvas.clientHeight,visible:v.z<1};}
  addFx(root,life,update){this.scene.add(root);this.fx.push({root,age:0,life,update});while(this.fx.length>55)this.dispose(this.fx.shift().root);}
  dispose(root){root.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];for(const m of mats)m.dispose();}});this.scene.remove(root);}
  sparks(x,y,z,color,count=22){const root=new T.Group();root.position.set(x,y,z);const items=[];for(let i=0;i<Math.round(count*this.settings.intensity);i++){const m=this.mesh(new T.OctahedronGeometry(.035+Math.random()*.04),this.basic(color,.9),root);const a=Math.random()*Math.PI*2,s=1+Math.random()*3;items.push({m,v:v3(Math.cos(a)*s,Math.random()*4+.5,Math.sin(a)*s)});}this.addFx(root,1,(p,dt)=>{for(const {m,v}of items){m.position.addScaledVector(v,dt);v.y-=7*dt;m.material.opacity=1-p;}});}
  onRelease(e){const color=SKILLS[e.id].color;if(e.id==='beam'){const root=new T.Group(),start=v3(e.origin.x,1.45,e.origin.z),end=v3(e.end.x,1.45,e.end.z),dir=end.clone().sub(start),len=dir.length();root.position.copy(start.clone().add(end).multiplyScalar(.5));root.quaternion.setFromUnitVectors(v3(0,1,0),dir.normalize());const outer=this.cylinder(.16,.16,len,this.basic(color,.32),root);const core=this.cylinder(.035,.035,len,this.basic('#efffff',.95),root);for(let i=0;i<18;i++)this.glow(color,1.5,root,[0,-len/2+len*i/17,0]);this.addFx(root,.65,p=>{root.scale.x=root.scale.z=Math.max(.01,1-p);outer.material.opacity=(1-p)*.32;core.material.opacity=1-p;});this.sparks(e.origin.x,1.4,e.origin.z,color,20);this.shake=.07;}
    if(e.id==='nova'){const root=new T.Group();root.position.set(e.aim.x,0,e.aim.z);const rune=this.rune(SKILLS.nova.radius,color,root,.08);rune.material.opacity=.8;const gem=this.mesh(new T.OctahedronGeometry(.6),this.basic('#c6acff'),root,[0,13,0]);gem.scale.y=2;this.glow(color,4,gem);this.addFx(root,.55,p=>{gem.position.y=13*(1-p)+.1;rune.rotation.z=p*2;rune.material.opacity=.4+p*.4;});}
    this.sparks(e.origin.x,1.5,e.origin.z,color,10);
  }
  impact(x,z,kind){const color=SKILLS[kind].color,root=new T.Group();root.position.set(x,.05,z);const nova=kind==='nova',r=nova?3.8:1;const rings=[this.ring(1,color,root,0,.025),this.ring(1,'#e7fffd',root,.04,.012),this.ring(1,color,root,.09,.04)];const g=this.glow(color,nova?12:4,root,[0,.6,0]);const rune=this.rune(r,color,root,.05);this.addFx(root,nova?1.5:.7,p=>{rings.forEach((m,i)=>{m.scale.setScalar((.15+p*(1+i*.15))*r);m.material.opacity=(1-p)*(.9-i*.15);});g.material.opacity=Math.pow(1-p,3);rune.material.opacity=(1-p)*.75;rune.rotation.z=p*.5;});this.sparks(x,.6,z,color,nova?65:20);this.shake=nova?.32:.12;
    if(nova){const shards=new T.Group();shards.position.set(x,0,z);const items=[];for(let i=0;i<18;i++){const a=i/18*Math.PI*2;const m=this.mesh(new T.OctahedronGeometry(.12+Math.random()*.14),this.standard('#9d91c2',.5,.3),shards,[Math.sin(a),.1,Math.cos(a)]);items.push({m,a,s:1+Math.random()*2});}this.addFx(shards,1.1,(p,dt)=>{for(const {m,a,s}of items){m.position.set(Math.sin(a)*(1+p*3),Math.max(.1,Math.sin(p*Math.PI)*s),Math.cos(a)*(1+p*3));m.rotation.x+=dt*4;m.rotation.z+=dt*2;m.scale.setScalar(1-p*.8);}});}
  }
  clear(){for(const f of this.fx)this.dispose(f.root);this.fx=[];for(const m of this.projectileViews.values())this.dispose(m);this.projectileViews.clear();this.floating=[];this.shake=0;}
  render(dt){const g=this.game,t=g.time,p=g.player,m=this.player,c=p.cast;this.renderer.shadowMap.enabled=this.settings.quality!=='low';this.player.root.position.set(p.x,0,p.z);this.player.root.rotation.y=p.angle;const walk=p.moving*Math.sin(t*10);m.body.position.y=Math.abs(walk)*.055;m.legs[0].rotation.x=walk*.45;m.legs[1].rotation.x=-walk*.45;m.arms[0].rotation.x=walk*.35;m.arms[1].rotation.x=c?-1.1-(c.elapsed/c.duration)*.6:-.18+walk*.12;m.arms[0].rotation.z=c?.65:.1;m.head.rotation.x=c?-.08:Math.sin(t*1.5)*.025;m.cape.rotation.x=.05+Math.sin(t*4)*.04+p.moving*.2;m.aura.rotation.y=t*.15;m.rune.material.opacity=c?.5:.18;m.staffGlow.material.color.set(c?SKILLS[c.id].color:'#70f4ce');m.staffGlow.material.opacity=.55+Math.sin(t*3)*.1;m.chargeGlow.visible=!!c;if(c){const s=1+c.elapsed/c.duration*2;m.chargeGlow.scale.set(s,s,s);m.chargeGlow.material.color.set(SKILLS[c.id].color);}
    for(let i=0;i<this.targets.length;i++){const view=this.targets[i],target=g.targets[i];view.root.visible=target.hp>0;view.body.position.y=1.3+Math.sin(t*2+i)*.05;view.stone.emissive.set(target.flash>0?'#7a4c36':'#000000');view.hp.scale.x=Math.max(.001,target.hp/target.maxHp);view.hp.position.x=-(1-target.hp/target.maxHp)*.55;view.hp.quaternion.copy(this.camera.quaternion);view.hpBack.quaternion.copy(this.camera.quaternion);}
    this.cursor.position.set(g.aim.x,.02,g.aim.z);this.cursor.rotation.y=t*.35;const s=g.selected==='nova'?SKILLS.nova.radius/.58:1;this.cursor.scale.setScalar(s);this.cursor.traverse(o=>{if(o.material)o.material.color.set(SKILLS[g.selected].color);});this.dust.rotation.y=t*.012;
    const active=new Set();for(const b of g.projectiles){active.add(b.id);let mesh=this.projectileViews.get(b.id);if(!mesh){mesh=new T.Group();this.mesh(new T.SphereGeometry(.16,12,8),this.basic('#fff0d4'),mesh);this.glow('#ff822f',2.7,mesh);for(let i=1;i<=6;i++)this.glow('#ff9c52',.6*(1-i/8),mesh,[-b.dx*i*.22,0,-b.dz*i*.22]);this.scene.add(mesh);this.projectileViews.set(b.id,mesh);}mesh.position.set(b.x,1.5,b.z);}for(const [id,mesh]of this.projectileViews)if(!active.has(id)){this.dispose(mesh);this.projectileViews.delete(id);}
    if(!g.paused){this.fx=this.fx.filter(f=>{f.age+=dt;f.update(clamp(f.age/f.life,0,1),dt);if(f.age>=f.life){this.dispose(f.root);return false;}return true;});for(const n of this.floating)n.life-=dt;this.floating=this.floating.filter(n=>n.life>0);this.shake=Math.max(0,this.shake-dt*.9);}
    this.camera.position.copy(this.baseCamera);if(this.settings.shake&&!g.paused){this.camera.position.x+=(Math.random()-.5)*this.shake;this.camera.position.y+=(Math.random()-.5)*this.shake;}this.camera.lookAt(this.lookAt);this.renderer.render(this.scene,this.camera);
    return this.floating.map(n=>({...this.project(n.x,3+(1-n.life/n.total)*1.5,n.z),text:n.damage,color:SKILLS[n.kind].color,alpha:Math.min(1,n.life*3)}));
  }
}
